package top.pxczxn.community.admin.editorial;
import cn.dev33.satoken.annotation.SaCheckPermission; import cn.dev33.satoken.stp.StpUtil; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import top.pxczxn.community.editorial.application.*; import top.pxczxn.platform.common.result.Result; import java.util.List;
@RestController @RequiredArgsConstructor @RequestMapping("/admin-api/community/editorial") public class AdminEditorialController { private final EditorialCollectionService service; @GetMapping @SaCheckPermission("community:editorial:list") public Result<List<EditorialCollectionView>> list(){return Result.ok(service.adminList());} @PostMapping @SaCheckPermission("community:editorial:manage") public Result<EditorialCollectionView> create(@RequestBody EditorialCollectionCommand command){return Result.ok(service.create(StpUtil.getLoginIdAsLong(),command));} @PutMapping("/{id}") @SaCheckPermission("community:editorial:manage") public Result<EditorialCollectionView> update(@PathVariable Long id,@RequestBody EditorialCollectionCommand command){return Result.ok(service.update(id,command));} }
